/**
 * TASK: Complete the ShelfTag record.
 *
 * The compact constructor must normalise every component BEFORE it is stored:
 *  - sku:      null becomes "", otherwise trimmed and upper-cased ("  ab-12 " -> "AB-12")
 *  - aisle:    null becomes "?", otherwise trimmed
 *  - quantity: any negative number becomes 0
 *
 * label() builds the printed tag as sku + " @ " + aisle + " x" + quantity.
 *
 * Example: new ShelfTag("  ab-12 ", " A3 ", -4).label() -> "AB-12 @ A3 x0"
 *
 * Because the record normalises its input, two tags written differently but
 * meaning the same thing must come out equal.
 */
public record ShelfTag(String sku, String aisle, int quantity) {

    public ShelfTag {
        sku = (sku == null) ? "" : sku.trim().toUpperCase();
        aisle = (aisle == null) ? "?" : aisle.trim();
        if (quantity < 0) {
            quantity = 0;
        }
    }

    public String label() {
        return sku + " @ " + aisle + " x" + quantity;
    }
}
